import Foundation

final class AshteTranslations: @unchecked Sendable {
	static let shared = AshteTranslations()

	let en: [String: String]
	let ar: [String: String]
	let ckb: [String: String]

	private init() {
		var en: [String: String] = [:]
		var ar: [String: String] = [:]
		var ckb: [String: String] = [:]
		if let data = AshteTranslations.json.data(using: .utf8),
		   let object = try? JSONSerialization.jsonObject(with: data) as? [String: [String: String]] {
			en = object["en"] ?? [:]
			ar = object["ar"] ?? [:]
			ckb = object["ckb"] ?? [:]
		}
		self.en = en
		self.ar = ar
		self.ckb = ckb
	}

